// SDK.md §5 sk derivation: determinism, contract/account binding, root
// classes, and the full §6.3 chain vector byte-for-byte.
//
// The chain vector (test/vectors/sk_derivation_chain.json) was generated by
// the aguilar1x/stellar-confidential-token-sdk conformance package against the
// same SDK.md §5.1 formulas — an INDEPENDENT implementation, so agreement here
// is two clients deriving the same account, which is the property §5 exists
// for. It is not (yet) published in OpenZeppelin's upstream testdata; if
// upstream lands an official vector, prefer that file. Per §6.1 discipline the
// test READS the file — no expected value is transcribed into this source.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { Keypair } from "@stellar/stellar-sdk";

import {
  SK_DOMAIN,
  SEP53_PREFIX,
  le4,
  skSigningMessage,
  sep53Payload,
  skSigningPayload,
  deriveSkFromRoot,
  deriveSk,
} from "../src/crypto/sk-derivation.ts";
import { addressToField } from "../src/crypto/address.ts";
import { deriveKeys } from "../src/crypto/keys.ts";
import { vkFromSk } from "../src/crypto/poseidon2.ts";
import { H, scalarMul, Grumpkin } from "../src/crypto/grumpkin.ts";
import { FR_MODULUS } from "../src/crypto/constants.ts";
import { toHex32, bytesToHex, hexToBytes } from "../src/crypto/field.ts";

let pass = 0, fail = 0;
const ok = (cond, msg) => { if (cond) { pass++; } else { fail++; console.error("  ✗ " + msg); } };

const CONTRACT = "CCREDIB3DG3IBVUKBL7QMEK4MTPSTODR7MQ34QY4SQ5LZ5L4WFWNVNXG";
const CONTRACT2 = "CBFOJTALVTO3LPZZHEXDD44K7RQKQJGAASF6XOKP5FWZD6WYKV4WN7HF";
const ACCOUNT = "GA5ZSEJYB37JRC5AVCIA5MOP4RHTM335X2KGX3IHOJAPP5RE34K4KZVN";
const ACCOUNT2 = "GBRPYHIL2CI3FNQ4BXLFMNDLFJUNPU2HY3ZMFSHONUCEOASW7QC7OX2H";

// --- le_4 encoding -----------------------------------------------------------
ok(bytesToHex(le4(0)) === "00000000", "le4(0)");
ok(bytesToHex(le4(1)) === "01000000", "le4(1) is little-endian");
ok(bytesToHex(le4(0x01020304)) === "04030201", "le4(0x01020304)");
ok((() => { try { le4(-1); return false; } catch { return true; } })(), "le4 rejects negatives");

// --- message shape -----------------------------------------------------------
const msg = skSigningMessage(CONTRACT, ACCOUNT);
ok(
  new TextDecoder().decode(msg) === `${SK_DOMAIN}\n${CONTRACT}\n${ACCOUNT}`,
  "signing message is domain \\n contract \\n account",
);
ok(msg.length === SK_DOMAIN.length + 1 + 56 + 1 + 56, "signing message is 151 bytes");
ok(SEP53_PREFIX.length === 24, "SEP-0053 prefix is 24 ASCII bytes");
ok(sep53Payload(msg).length === 32, "SEP-0053 payload is a 32-byte digest");
ok(
  bytesToHex(skSigningPayload(CONTRACT, ACCOUNT)) === bytesToHex(sep53Payload(msg)),
  "skSigningPayload == sep53Payload(skSigningMessage)",
);

// --- determinism and binding (raw roots) --------------------------------------
const root32 = new Uint8Array(32).fill(0xab);
const a = deriveSk(root32, CONTRACT, ACCOUNT);
const b = deriveSk(root32, CONTRACT, ACCOUNT);
ok(a.sk === b.sk && a.vk === b.vk && a.j === b.j, "same root/contract/account -> same sk");
ok(a.sk > 0n && a.sk < FR_MODULUS, "sk is in [1, r)");
ok(a.vk !== 0n, "vk is nonzero");
ok(a.vk === vkFromSk(a.sk, a.addrF), "vk matches vkFromSk(sk, addr_f)");
ok(deriveSk(root32, CONTRACT2, ACCOUNT).sk !== a.sk, "different contract -> different sk");
ok(deriveSk(root32, CONTRACT, ACCOUNT2).sk !== a.sk, "different account -> different sk");
const otherRoot = new Uint8Array(32).fill(0xcd);
ok(deriveSk(otherRoot, CONTRACT, ACCOUNT).sk !== a.sk, "different root -> different sk");
ok(
  (() => { try { deriveSkFromRoot(new Uint8Array(0), 1n, 2n); return false; } catch { return true; } })(),
  "empty root rejected",
);

// --- §5.2 end-to-end with a fixed local signer --------------------------------
const kp = Keypair.fromRawEd25519Seed(Buffer.alloc(32, 0x22));
const sig = new Uint8Array(kp.sign(Buffer.from(skSigningPayload(CONTRACT, ACCOUNT))));
ok(sig.length === 64, "ed25519 signature root is 64 bytes");
const derived = deriveSk(sig, CONTRACT, ACCOUNT);
const keys = deriveKeys(derived.sk, derived.addrF);
ok(keys.vk === derived.vk, "deriveKeys agrees on vk");
ok(scalarMul(derived.sk, H).equals(keys.Y), "Y = sk * H");
ok(scalarMul(derived.vk, H).equals(keys.PVK), "PVK = vk * H");
// RFC 8032 determinism: signing the same payload again yields the same root.
const sig2 = new Uint8Array(kp.sign(Buffer.from(skSigningPayload(CONTRACT, ACCOUNT))));
ok(bytesToHex(sig2) === bytesToHex(sig), "signer root is deterministic");
ok(deriveSk(sig2, CONTRACT, ACCOUNT).sk === derived.sk, "re-signing recovers the same sk");

// --- the §6.3 chain vector, byte-for-byte --------------------------------------
const here = dirname(fileURLToPath(import.meta.url));
const doc = JSON.parse(readFileSync(join(here, "vectors", "sk_derivation_chain.json"), "utf8"));
for (const vec of doc.vectors) {
  const { inputs, intermediate: mid, output } = vec;

  ok(SK_DOMAIN === mid.sk_domain, "vector: SK_DOMAIN");
  ok(SEP53_PREFIX === mid.sep53_prefix, "vector: SEP-0053 prefix");

  const vMsg = skSigningMessage(inputs.contract, inputs.account);
  ok(new TextDecoder().decode(vMsg) === mid.signed_message_utf8, "vector: message utf8");
  ok("0x" + bytesToHex(vMsg) === mid.signed_message_hex, "vector: message hex");

  const vPayload = sep53Payload(vMsg);
  ok("0x" + bytesToHex(vPayload) === mid.sep53_payload_sha256, "vector: SEP-0053 payload sha256");

  const vKp = Keypair.fromRawEd25519Seed(Buffer.from(hexToBytes(inputs.ed25519_seed)));
  const vSig = new Uint8Array(vKp.sign(Buffer.from(vPayload)));
  ok("0x" + bytesToHex(vSig) === mid.root_signature, "vector: root signature hex");
  ok(Buffer.from(vSig).toString("base64") === mid.root_signature_base64, "vector: root signature base64");

  const addrF = addressToField(inputs.contract);
  const acctF = addressToField(inputs.account);
  ok(toHex32(addrF) === mid.addr_f, "vector: addr_f");
  ok(toHex32(acctF) === mid.acct_f, "vector: acct_f");

  const res = deriveSk(vSig, inputs.contract, inputs.account);
  ok(res.j === mid.rejection_counter_j, "vector: rejection counter j");
  ok(toHex32(res.sk) === output.sk, "vector: sk");
  ok(toHex32(res.vk) === output.vk, "vector: vk");

  const Y = scalarMul(res.sk, H).toAffine();
  ok(toHex32(Y.x) === output.Y.x && toHex32(Y.y) === output.Y.y, "vector: Y = sk * H");
  const PVK = scalarMul(res.vk, H).toAffine();
  ok(toHex32(PVK.x) === output.PVK.x && toHex32(PVK.y) === output.PVK.y, "vector: PVK = vk * H");

  // The points the vector pins are on-curve under our own curve config.
  Grumpkin.fromAffine(Y);
  Grumpkin.fromAffine(PVK);
  pass++;
}

console.log(`sk-derivation: ${pass} passed, ${fail} failed`);
process.exit(fail === 0 ? 0 : 1);
